"""Brand identity, accessible UI roles and color-vision checks are separate.

The seed remains exact at ramp stop 600. Only UI roles move along the OKLCH
ramp. These pairs describe the actual React surfaces in workspace.css; a
redesign must update the surfaces and the measured acceptance fixtures.
"""
import copy
import math
import re
from functools import lru_cache

LIGHTNESS = (.9695, .9317, .8597, .7634, .6718, .5899, .5015, .4303, .3772, .339, .2278)
CHROMA = (.11, .247, .486, .765, 1.021, 1.111, 1., .789, .63, .508, .334)
SURFACES = {
    "light": ("#f7f8fa", "#ffffff", "#eef0f3"),
    "dark": ("#13171c", "#1b2028", "#252c35"),
}
DEFAULT = "#ba352c"
MACHADO = (
    ((.367322, .860646, -.227968), (.280085, .672501, .047413), (-.011820, .042940, .968881)),
    ((.152286, 1.052583, -.204868), (.114503, .786281, .099216), (-.003882, -.048116, 1.051998)),
)


def normalize(value):
    if not isinstance(value, str) or not re.fullmatch(r"#[0-9a-fA-F]{3}(?:[0-9a-fA-F]{3})?", value):
        return None
    return ("#"+"".join(c*2 for c in value[1:]) if len(value) == 4 else value).lower()


def linear(hex_value):
    rgb = tuple(int(hex_value[i:i+2], 16)/255 for i in (1, 3, 5))
    return tuple(v/12.92 if v <= .04045 else ((v+.055)/1.055)**2.4 for v in rgb)


def to_hex(rgb):
    def channel(value):
        value = max(0., min(1., value))
        encoded = 12.92*value if value <= .0031308 else 1.055*value**(1/2.4)-.055
        return max(0, min(255, math.floor(encoded*255+.5)))
    return "#"+"".join(f"{channel(v):02x}" for v in rgb)


def lab(rgb):
    r, g, b = rgb
    ll = math.cbrt(.4122214708*r+.5363325363*g+.0514459929*b)
    mm = math.cbrt(.2119034982*r+.6806995451*g+.1073969566*b)
    ss = math.cbrt(.0883024619*r+.2817188376*g+.6299787005*b)
    return (.2104542553*ll+.793617785*mm-.0040720468*ss,
        1.9779984951*ll-2.428592205*mm+.4505937099*ss,
        .0259040371*ll+.7827717662*mm-.808675766*ss)


def lch(hex_value):
    lightness, aa, bb = lab(linear(hex_value))
    return lightness, math.hypot(aa, bb), math.degrees(math.atan2(bb, aa)) % 360


def from_lch(lightness, chroma, hue):
    lightness = max(0., min(1., lightness))
    hue = math.radians(hue)
    def rgb(c):
        aa, bb = c*math.cos(hue), c*math.sin(hue)
        ll = (lightness+.3963377774*aa+.2158037573*bb)**3
        mm = (lightness-.1055613458*aa-.0638541728*bb)**3
        ss = (lightness-.0894841775*aa-1.291485548*bb)**3
        return (4.0767416621*ll-3.3077115913*mm+.2309699292*ss,
            -1.2684380046*ll+2.6097574011*mm-.3413193965*ss,
            -.0041960863*ll-.7034186147*mm+1.707614701*ss)
    candidate = rgb(chroma)
    if all(-1e-7 <= v <= 1+1e-7 for v in candidate):
        return to_hex(candidate)
    low, high = 0., chroma
    for _ in range(24):
        middle = (low+high)/2
        if all(0 <= v <= 1 for v in rgb(middle)):
            low = middle
        else:
            high = middle
    return to_hex(rgb(low))


def ramp(seed):
    seed = normalize(seed)
    if seed is None:
        raise ValueError("invalid_brand_seed")
    ls, cs, hue = lch(seed)
    stops = []
    for i, value in enumerate(LIGHTNESS):
        li = LIGHTNESS[0]+(value-LIGHTNESS[0])*(ls-LIGHTNESS[0])/(LIGHTNESS[6]-LIGHTNESS[0]) if i <= 6 else ls+(value-LIGHTNESS[6])*(LIGHTNESS[10]-ls)/(LIGHTNESS[10]-LIGHTNESS[6])
        stops.append(from_lch(li, cs*CHROMA[i], hue))
    stops[6] = seed
    return stops


def contrast(a, b):
    def luminance(color):
        r, g, bb = linear(color)
        return .2126*r+.7152*g+.0722*bb
    la, lb = luminance(a), luminance(b)
    return (max(la, lb)+.05)/(min(la, lb)+.05)


def foreground(background):
    return max(("#ffffff", "#000000"), key=lambda value: contrast(value, background))


def mix(color, opacity, background):
    # Browser alpha composition happens in encoded sRGB, not linear light.
    return "#"+"".join(f"{math.floor(int(color[i:i+2], 16)*opacity+int(background[i:i+2], 16)*(1-opacity)+.5):02x}" for i in (1, 3, 5))


def simulated_distance(a, b):
    def simulated(color, matrix):
        rgb = linear(color)
        return lab(tuple(max(0., min(1., sum(m*v for m, v in zip(row, rgb, strict=True)))) for row in matrix))
    return min(math.dist(simulated(a, m), simulated(b, m)) for m in MACHADO)


def role(stops, surfaces, *, target, minimum=4.5):
    valid = [color for color in stops if min(contrast(color, surface) for surface in surfaces) >= minimum]
    # Include gamut-mapped lightness samples for extreme seeds whose original
    # ramp has no suitable stop. Hue and chroma remain the brand's input.
    if not valid:
        _, chroma, hue = lch(stops[6])
        valid = [from_lch(i/100, chroma, hue) for i in range(4, 97, 2)
            if min(contrast(from_lch(i/100, chroma, hue), surface) for surface in surfaces) >= minimum]
    if not valid:
        raise ValueError("accessible_role_unavailable")
    return min(valid, key=lambda color: abs(lch(color)[0]-target))


def semantic(seed, surfaces, accent):
    lightness, chroma, hue = lch(seed)
    variants = []
    for rotation in (0, *[sign*step for step in range(5, 61, 5) for sign in (1, -1)]):
        candidate = from_lch(lightness, chroma, hue+rotation)
        chosen = role(ramp(candidate), surfaces, target=lightness)
        distance = simulated_distance(chosen, accent)
        variants.append((chosen, distance, rotation))

        variants.append((chosen, distance, rotation))
        if distance >= .05:
            return chosen, False
    return max(variants, key=lambda item: item[1])[0], True


@lru_cache(maxsize=128)
def _derive(seed):
    identity = normalize(seed) or DEFAULT
    stops = ramp(identity)
    warnings = []
    # Achromatic identity is retained for logos, while controls keep the
    # product's distinct accent, matching the original role separation.
    achromatic = lch(identity)[1] < .01
    if achromatic:
        stops = ramp(DEFAULT)
        warnings.append("semente_acromatica")
    result = {"brand": identity, "ramp": ramp(identity), "warnings": warnings}
    for theme, surfaces in SURFACES.items():
        primary = role(stops, surfaces, target=.68 if theme == "dark" else lch(identity)[0])
        primary_hover = role(stops, surfaces, target=lch(primary)[0]+(.06 if theme == "dark" else -.06))
        # The same foreground must stay readable while hovering the button.
        on_primary = foreground(primary)
        if contrast(on_primary, primary_hover) < 4.5:
            primary_hover = primary
        focus = role(stops, surfaces, target=lch(primary)[0], minimum=3.)
        tokens = {"primary": primary, "primary-hover": primary_hover, "on-primary": on_primary,
            "focus": focus, "accent-soft": mix(primary, .12, surfaces[1]), "brand": identity}
        bases = {"success": "#356849", "warning": "#84580e", "danger": "#a13e35"} if theme == "light" else {"success": "#a4d4b5", "warning": "#f0c889", "danger": "#f0aaa4"}
        for name, base in bases.items():
            color, degraded = semantic(base, surfaces, primary)
            background = mix(color, .10, surfaces[1])
            if contrast(color, background) < 4.5:
                color = role(ramp(color), (*surfaces, background), target=lch(color)[0])
            tokens[name], tokens[name+"-bg"] = color, background
            if degraded:
                warnings.append("semantica_sem_separacao:"+theme+":"+name)
        result[theme] = tokens
    return result


def derive(seed=None):
    # Callers may attach presentation fields; never mutate cached data shared
    # by unrelated organizations with the same public brand color.
    return copy.deepcopy(_derive(normalize(seed) or DEFAULT))


def emergency_palette():
    light = {"primary": "#9c3028", "primary-hover": "#80261f", "on-primary": "#ffffff", "focus": "#9c3028", "accent-soft": "#f6e7e5", "brand": DEFAULT,
        "success": "#356849", "success-bg": "#eaf2ed", "warning": "#84580e", "warning-bg": "#fbf2df", "danger": "#a13e35", "danger-bg": "#f9ebe9"}
    dark = {"primary": "#ffaaa0", "primary-hover": "#ffc2bb", "on-primary": "#000000", "focus": "#ffaaa0", "accent-soft": "#402522", "brand": DEFAULT,
        "success": "#a4d4b5", "success-bg": "#253e2e", "warning": "#f0c889", "warning-bg": "#3e3323", "danger": "#f0aaa4", "danger-bg": "#462a28"}
    return {"brand": DEFAULT, "ramp": [], "warnings": ["derivacao_falhou"], "light": light, "dark": dark}

